  for(const d of readdirSync(path,{withFileTypes:true})) {
    const p=path+'/'+d.name;
    if(d.isDirectory()){if(d.name!=='target')visit(p); continue;}
    if(!p.endsWith('.ts'))continue;
    let source=readFileSync(p,'utf8'); if(!source.includes('Math.hypot'))continue;
    const ast=ts.createSourceFile(p,source,ts.ScriptTarget.Latest,true), positions:Array<[number,number]>=[];
    function node(n:ts.Node){
      if(ts.isCallExpression(n)&&n.arguments.length===2&&n.expression.getText(ast)==='Math.hypot'&&!n.arguments.some(ts.isSpreadElement))
        positions.push([n.expression.getStart(ast),n.expression.getEnd()]);
      ts.forEachChild(n,node);
    }
    node(ast); if(!positions.length)continue;
    for(const [a,b] of positions.sort((a,b)=>b[0]-a[0]))source=source.slice(0,a)+'hypot2'+source.slice(b);
    let imported=relative(dirname(p),helperPath);if(!imported.startsWith('.'))imported='./'+imported;
    source=`import {hypot2} from '${imported}';\n`+source;
    writeFileSync(p,source);changed.push({file:relative(cwd,p),calls:positions.length});
  }
}
visit(cwd+'/scripts/lib'); visit(cwd+'/scripts/v0');
writeFileSync(helperPath,helper);writeFileSync(study+'/hypot2.ts',helper);
writeFileSync(study+'/replacements.json',JSON.stringify(changed,null,2)+'\n');
symlinkSync(root+'/node_modules',cwd+'/node_modules');

