      let previous = incoming, sum = 0;
      for (const v of vs) {
        const angle = Math.atan2(v.y, v.x) - Math.atan2(previous.y, previous.x);
        sum += (hypot2(v.x, v.y) + hypot2(previous.x, previous.y)) / 2 * Math.abs(Math.atan2(Math.sin(angle), Math.cos(angle)));
